package com.bedlessfighter.necroManager.commands;
import com.bedlessfighter.necroManager.managers.*;import org.bukkit.command.*;import org.bukkit.entity.Player;import org.bukkit.inventory.ItemStack;import org.jetbrains.annotations.NotNull;
public final class MoreCommand implements CommandExecutor {
 @Override public boolean onCommand(@NotNull CommandSender s,@NotNull Command c,@NotNull String[] a){if(!(s instanceof Player p)){MessageManager.send(s,"messages.player-required","&cOnly players can use this command.");return true;}if(!PermissionManager.has(s,"necromanager.more")){MessageManager.send(s,"messages.no-perm","&cNo permission.");return true;}if(a.length!=0){MessageManager.sendRaw(s,"&cUsage: /more");return true;}ItemStack item=p.getInventory().getItemInMainHand();if(item.getType().isAir()){MessageManager.sendRaw(s,"&cHold an item first.");return true;}item.setAmount(item.getMaxStackSize());p.getInventory().setItemInMainHand(item);MessageManager.sendRaw(s,"&aYour held stack was filled.");return true;}
}